/**
 * TASK: Design a Square that does NOT break substitutability.
 *
 * The classic Liskov trap: making Square extend Rectangle. Rectangle promises
 * that setWidth(5) then setHeight(4) gives area 20. A Square that keeps its
 * sides equal cannot keep that promise, so code holding a Rectangle reference
 * would silently misbehave. The fix is to share the INTERFACE, not the class.
 *
 * Rectangle (provided) implements Shape. You write SquareSafe:
 *   - it implements Shape, and it must NOT extend Rectangle
 *   - setSide(double side) stores one side length
 *   - area() returns side * side
 *   - name() returns "Square"
 *   - static String describe(Shape shape) returns name() + " area=" + area(),
 *     e.g. "Rectangle area=12.0" or "Square area=25.0"
 *
 * describe() takes a Shape, so it works for every shape ever written -- that is
 * polymorphism without an unsafe inheritance relationship.
 */
// Provided -- do not edit.
interface Shape {

    double area();

    String name();
}

// Provided -- do not edit.
class Rectangle implements Shape {

    private double width;
    private double height;

    public void setWidth(double width) {
        this.width = width;
    }

    public void setHeight(double height) {
        this.height = height;
    }

    @Override
    public double area() {
        return width * height;
    }

    @Override
    public String name() {
        return "Rectangle";
    }
}

