public class SquareSafeTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        SquareSafe square = new SquareSafe();
        square.setSide(5.0);
        check("square area", 25.0, square.area());
        check("square name", "Square", square.name());
        check("describe(square)", "Square area=25.0", SquareSafe.describe(square));

        Rectangle rect = new Rectangle();
        rect.setWidth(3.0);
        rect.setHeight(4.0);
        check("describe(rectangle)", "Rectangle area=12.0", SquareSafe.describe(rect));

        // Substitutability: SquareSafe is a Shape, and deliberately NOT a Rectangle.
        check("SquareSafe implements Shape", true, Shape.class.isAssignableFrom(SquareSafe.class));
        check("SquareSafe does not extend Rectangle", false,
                Rectangle.class.isAssignableFrom(SquareSafe.class));

        // Rectangle keeps its own contract: setWidth then setHeight are independent.
        rect.setWidth(5.0);
        rect.setHeight(4.0);
        check("rectangle sides stay independent", 20.0, rect.area());

        SquareSafe other = new SquareSafe();
        other.setSide(2.0);
        Shape[] shapes = { rect, other };
        double total = 0.0;
        for (Shape s : shapes) {
            total += s.area();
        }
        check("polymorphic total area", 24.0, total);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

